    void saveStoresVehicleThatCanBeReadBack() {
        Vehicle saved = vehicleRepository.save(
                new Vehicle(VIN, "Ford", "Focus", 2026, FuelType.ELECTRIC, LocalDate.of(2027, 3, 1)));
